import networkx as nx
import random

def get_girth(G):
    girth = float('inf')
    for n in G.nodes():
        # BFS to find shortest cycle
        dist = {n: 0}
        parent = {n: None}
        q = [n]
        while q:
            u = q.pop(0)
            for v in G.neighbors(u):
                if v == parent[u]:
                    continue
                if v in dist:
                    girth = min(girth, dist[u] + dist[v] + 1)
                else:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
    return girth

def solve():
    for attempt in range(100):
        G = nx.Graph()
        G.add_nodes_from(range(26))
        edges = list(nx.non_edges(G))
        random.shuffle(edges)

        for u, v in edges:
            if G.degree(u) < 3 and G.degree(v) < 3:
                G.add_edge(u, v)
                if get_girth(G) < 7:
                    G.remove_edge(u, v)

        # Try to satisfy min degree 3
        for u in range(26):
            while G.degree(u) < 3:
                candidates = [v for v in range(26) if v != u and G.degree(v) < 5 and not G.has_edge(u, v)]
                random.shuffle(candidates)
                added = False
                for v in candidates:
                    G.add_edge(u, v)
                    if get_girth(G) >= 7:
                        added = True
                        break
                    G.remove_edge(u, v)
                if not added:
                    break

        if all(3 <= G.degree(n) <= 5 for n in G.nodes()) and get_girth(G) >= 7:
            print("Found!")
            print(list(G.edges()))
            return
    print("Not found")

solve()

