from pysat.solvers import Glucose3

def solve():
    n = 26
    solver = Glucose3()

    # Variables: x_{i,j} for 0 <= i < j < n
    def var(i, j):
        if i > j:
            i, j = j, i
        return i * n + j + 1

    # Degree constraints: between 3 and 5
    from itertools import combinations

    for i in range(n):
        edges_i = [var(i, j) for j in range(n) if i != j]

        # At least 3
        # Not all combinations of n-3 are false
        # Actually, we can use cardinality constraints, but n=26 is small enough for simple encoding
        # Or we can use pysat.card
        from pysat.card import CardEnc

        # At least 3
        cnf_at_least = CardEnc.atleast(lits=edges_i, bound=3, vpool=None)
        for clause in cnf_at_least.clauses:
            solver.add_clause(clause)

        # At most 5
        cnf_at_most = CardEnc.atmost(lits=edges_i, bound=5, vpool=None)
        for clause in cnf_at_most.clauses:
            solver.add_clause(clause)

    # Girth >= 7 means no cycles of length 3, 4, 5, 6
    # No 3-cycles
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                solver.add_clause([-var(i, j), -var(j, k), -var(i, k)])

    # No 4-cycles
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                for l in range(k+1, n):
                    # 3 possible 4-cycles on 4 vertices
                    solver.add_clause([-var(i, j), -var(j, k), -var(k, l), -var(i, l)])
                    solver.add_clause([-var(i, j), -var(j, l), -var(l, k), -var(i, k)])
                    solver.add_clause([-var(i, k), -var(k, j), -var(j, l), -var(i, l)])

    # No 5-cycles
    # There are 12 possible 5-cycles on 5 vertices
    import itertools
    for c in itertools.combinations(range(n), 5):
        for p in itertools.permutations(c):
            if p[0] < p[1] and p[0] < p[4] and p[1] < p[4]:
                solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[4]), -var(p[4], p[0])])

    # No 6-cycles
    # There are 60 possible 6-cycles on 6 vertices
    # This might be too many clauses: C(26, 6) * 60 = 230,230 * 60 = 13,813,800 clauses.
    # Let's see if we can just generate it and solve it.
    print("Adding 6-cycles...")
    count = 0
    for c in itertools.combinations(range(n), 6):
        for p in itertools.permutations(c):
            if p[0] < p[1] and p[0] < p[5] and p[1] < p[5]:
                solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[4]), -var(p[4], p[5]), -var(p[5], p[0])])
                count += 1
    print(f"Added {count} 6-cycle clauses.")

    print("Solving...")
    if solver.solve():
        print("SAT")
        model = solver.get_model()
        edges = []
        for i in range(n):
            for j in range(i+1, n):
                if model[var(i, j) - 1] > 0:
                    edges.append((i, j))
        print(edges)
    else:
        print("UNSAT")

